source .venv/bin/activate && python - << 'PY'
import json, re, requests, time
allp=json.load(open('/tmp/all_papers.json')); sel=json.load(open('/tmp/selected.json'))
EXTRA=["We're Afraid Language Models Aren't Modeling Ambiguity","Extending Epistemic Uncertainty Beyond Parameters",
"Don't Start What You Can't Finish","SAFETY SENTRY","CollabLLM","AmbigQA"]
def sid(u):
    m=re.search(r'/paper/([0-9a-f]{40})',u or '');  return m.group(1) if m else (('CorpusId:'+re.search(r'CorpusId:(\d+)',u,re.I).group(1)) if re.search(r'CorpusId:(\d+)',u or '',re.I) else None)
add=[]
have={r['title'] for r in sel}
for k in EXTRA:
    for r in allp:
        if k.lower() in r['title'].lower() and r['title'] not in have:
            r['sid']=sid(r['url']); add.append(r); have.add(r['title']); break
print("extra found:",[r['title'][:60] for r in add])
if add:
    ids=[r['sid'] for r in add]
    resp=requests.post("https://api.semanticscholar.org/graph/v1/paper/batch",
        params={'fields':'title,year,externalIds,openAccessPdf,venue'}, json={'ids':ids}, timeout=60).json()
    for r,m in zip(add,resp):
        m=m or {}
        r['arxiv']=(m.get('externalIds') or {}).get('ArXiv'); r['pdf']=(m.get('openAccessPdf') or {}).get('url'); r['venue']=m.get('venue')
sel.extend(add)
nolink=[r['title'] for r in sel if not r.get('arxiv') and not r.get('pdf')]
print("total",len(sel),"no link:",len(nolink)); print(nolink)
json.dump(sel, open('/tmp/selected.json','w'), indent=1)
PY

source .venv/bin/activate && python - << 'PY'
import json, re, os, time, requests
sel=json.load(open('/tmp/selected.json'))
os.makedirs('papers', exist_ok=True)
def slug(t):
    s=re.sub(r'[^a-zA-Z0-9 ]','',t).strip().lower()
    return '_'.join(s.split()[:7])
ok=[];fail=[]
H={'User-Agent':'Mozilla/5.0 (research literature review)'}
for r in sel:
    name=(r['arxiv'].replace('/','_')+'_' if r.get('arxiv') else '')+slug(r['title'])+'.pdf'
    path='papers/'+name
    r['file']=path
    if os.path.exists(path) and os.path.getsize(path)>20000:
        ok.append(r['title']); continue
    urls=[]
    if r.get('arxiv'): urls.append(f"https://arxiv.org/pdf/{r['arxiv']}")
    if r.get('pdf'): urls.append(r['pdf'])
    got=False
    for u in urls:
        try:
            resp=requests.get(u, headers=H, timeout=90, allow_redirects=True)
            if resp.status_code==200 and resp.content[:4]==b'%PDF' and len(resp.content)>20000:
                open(path,'wb').write(resp.content); got=True; break
        except Exception as e:
            pass
        time.sleep(1)
    (ok if got else fail).append(r['title'])
    time.sleep(1.2)
print(f"OK={len(ok)} FAIL={len(fail)}")
for t in fail: print("FAIL:",t)
json.dump(sel, open('/tmp/selected.json','w'), indent=1)
