import json, os, requests, time, re
sel=json.load(open('/tmp/selected.json'))
fails=[r for r in sel if not os.path.exists(r['file']) or os.path.getsize(r['file'])<20000]
H={'User-Agent':'Mozilla/5.0'}
# try arxiv API title search
import xml.etree.ElementTree as ET
for r in fails:
    q=re.sub(r'[^a-zA-Z0-9 ]',' ',r['title'])
    u="http://export.arxiv.org/api/query"
    try:
        resp=requests.get(u, params={'search_query':f'ti:"{q[:80]}"','max_results':3}, timeout=60)
        root=ET.fromstring(resp.text)
        ns={'a':'http://www.w3.org/2005/Atom'}
        found=None
        for e in root.findall('a:entry',ns):
            t=e.find('a:title',ns).text.strip()
            if t.lower()[:40]==r['title'].lower()[:40]:
                found=e.find('a:id',ns).text; break
        print(r['title'][:55],'->',found)
        if found:
            aid=found.rsplit('/',1)[-1]
            pdf=requests.get(f"https://arxiv.org/pdf/{aid}",headers=H,timeout=90)
            if pdf.content[:4]==b'%PDF':
                open(r['file'],'wb').write(pdf.content); print("  downloaded", r['file'])
    except Exception as e: print("err",e)
    time.sleep(3)
