import json, os, collections
from datasets import load_from_disk
os.makedirs('datasets/samples',exist_ok=True)
summary={}
for name in sorted(os.listdir('datasets')):
    p=f'datasets/{name}'
    if not os.path.isdir(p) or name=='samples': continue
    try:
        d=load_from_disk(p)
        sp={k:len(v) for k,v in d.items()}
        first=list(d)[0]
        cols=d[first].column_names
        sample=[{c:(str(d[first][i][c])[:400]) for c in cols} for i in range(min(3,len(d[first])))]
